import numpy as np
import pandas as pd
from scipy.stats import skew, kurtosis
from sklearn.feature_selection import VarianceThreshold, SelectKBest, f_classif
import joblib
import os

class KeystrokeFeatureExtractor:
    """
    Extracts keystroke dynamics features from raw keyboard events.
    Features:
    - Key hold time (mean, std, median, min, max)
    - Flight times F1, F2, F3, F4 (mean, std, median, min, max)
    - Typing speed (keys per second)
    - Keystroke count
    """
    def __init__(self):
        # Define the complete list of features generated by this extractor
        self.feature_names = [
            "key_hold_time_mean", "key_hold_time_std", "key_hold_time_median", "key_hold_time_min", "key_hold_time_max",
            "flight_time_f1_mean", "flight_time_f1_std", "flight_time_f1_median", "flight_time_f1_min", "flight_time_f1_max",
            "flight_time_f2_mean", "flight_time_f2_std", "flight_time_f2_median", "flight_time_f2_min", "flight_time_f2_max",
            "flight_time_f3_mean", "flight_time_f3_std", "flight_time_f3_median", "flight_time_f3_min", "flight_time_f3_max",
            "flight_time_f4_mean", "flight_time_f4_std", "flight_time_f4_median", "flight_time_f4_min", "flight_time_f4_max",
            "typing_speed", "keystroke_count"
        ]

    def extract(self, key_df, duration_seconds=300.0):
        """
        Extracts features from key_df.
        key_df columns: ['key', 'direction', 'time'] (direction: 0=press, 1=release)
        """
        features = {name: np.nan for name in self.feature_names}
        features["keystroke_count"] = 0.0
        features["typing_speed"] = 0.0

        if key_df is None or len(key_df) == 0:
            return features

        # Ensure sorted by time
        df = key_df.sort_values(by="time").copy()
        features["keystroke_count"] = float(len(df[df["direction"] == 0]))
        features["typing_speed"] = features["keystroke_count"] / max(duration_seconds, 1.0)

        # 1. Match presses and releases to get Key Hold Times
        active_presses = {}
        paired_keys = []  # List of dicts: {'key': key, 'press_time': t_press, 'release_time': t_release}
        hold_times = []

        for _, row in df.iterrows():
            key = str(row["key"])
            direction = int(row["direction"])
            t = row["time"]

            if direction == 0:
                active_presses[key] = t
            elif direction == 1:
                if key in active_presses:
                    t_press = active_presses[key]
                    hold = (t - t_press).total_seconds()
                    hold_times.append(hold)
                    paired_keys.append({
                        "key": key,
                        "press_time": t_press,
                        "release_time": t
                    })
                    del active_presses[key]

        # Calculate hold time stats
        if hold_times:
            features["key_hold_time_mean"] = float(np.mean(hold_times))
            features["key_hold_time_std"] = float(np.std(hold_times)) if len(hold_times) > 1 else 0.0
            features["key_hold_time_median"] = float(np.median(hold_times))
            features["key_hold_time_min"] = float(np.min(hold_times))
            features["key_hold_time_max"] = float(np.max(hold_times))

        # 2. Compute Flight Times between consecutive completed key presses
        # Sort paired keys by press_time
        paired_keys = sorted(paired_keys, key=lambda x: x["press_time"])
        
        f1_list, f2_list, f3_list, f4_list = [], [], [], []
        for i in range(len(paired_keys) - 1):
            k_curr = paired_keys[i]
            k_next = paired_keys[i+1]

            # F1 (Up-Down): press(i+1) - release(i)
            f1 = (k_next["press_time"] - k_curr["release_time"]).total_seconds()
            # F2 (Up-Up): release(i+1) - release(i)
            f2 = (k_next["release_time"] - k_curr["release_time"]).total_seconds()
            # F3 (Down-Down): press(i+1) - press(i)
            f3 = (k_next["press_time"] - k_curr["press_time"]).total_seconds()
            # F4 (Down-Up): release(i+1) - press(i)
            f4 = (k_next["release_time"] - k_curr["press_time"]).total_seconds()

            f1_list.append(f1)
            f2_list.append(f2)
            f3_list.append(f3)
            f4_list.append(f4)

        def add_stats(lst, prefix):
            if lst:
                features[f"{prefix}_mean"] = float(np.mean(lst))
                features[f"{prefix}_std"] = float(np.std(lst)) if len(lst) > 1 else 0.0
                features[f"{prefix}_median"] = float(np.median(lst))
                features[f"{prefix}_min"] = float(np.min(lst))
                features[f"{prefix}_max"] = float(np.max(lst))

        add_stats(f1_list, "flight_time_f1")
        add_stats(f2_list, "flight_time_f2")
        add_stats(f3_list, "flight_time_f3")
        add_stats(f4_list, "flight_time_f4")

        return features


class TouchFeatureExtractor:
    """
    Extracts swipe and tap features from TouchEvent data.
    Features:
    - Swipe count, Tap count
    - Swipe distance (mean, std, median, min, max)
    - Swipe duration (mean, std, median, min, max)
    - Swipe speed (mean, std, median, min, max)
    - Swipe direction (mean, std, median, min, max)
    - Swipe instantaneous velocity (mean, std)
    - Swipe instantaneous acceleration (mean, std)
    - Tap duration (mean, std, median, min, max)
    - Pressure (mean, std, median, min, max)
    - Touch area (mean, std, median, min, max)
    - Finger orientation (mean, std, median, min, max)
    """
    def __init__(self, swipe_threshold=20.0):
        self.swipe_threshold = swipe_threshold
        self.feature_names = [
            "swipe_count", "tap_count",
            "swipe_dist_mean", "swipe_dist_std", "swipe_dist_median", "swipe_dist_min", "swipe_dist_max",
            "swipe_dur_mean", "swipe_dur_std", "swipe_dur_median", "swipe_dur_min", "swipe_dur_max",
            "swipe_speed_mean", "swipe_speed_std", "swipe_speed_median", "swipe_speed_min", "swipe_speed_max",
            "swipe_dir_mean", "swipe_dir_std", "swipe_dir_median", "swipe_dir_min", "swipe_dir_max",
            "swipe_inst_vel_mean", "swipe_inst_vel_std",
            "swipe_inst_acc_mean", "swipe_inst_acc_std",
            "tap_dur_mean", "tap_dur_std", "tap_dur_median", "tap_dur_min", "tap_dur_max",
            "touch_press_mean", "touch_press_std", "touch_press_median", "touch_press_min", "touch_press_max",
            "touch_area_mean", "touch_area_std", "touch_area_median", "touch_area_min", "touch_area_max",
            "touch_orient_mean", "touch_orient_std", "touch_orient_median", "touch_orient_min", "touch_orient_max"
        ]

    def extract(self, touch_df):
        """
        Extracts features from touch_df.
        touch_df columns: ['Xvalue', 'Yvalue', 'pressure', 'touchMajor', 'touchMinor', 'pointerID', 'fingerOrientation', 'actionType', 'time']
        """
        features = {name: np.nan for name in self.feature_names}
        features["swipe_count"] = 0.0
        features["tap_count"] = 0.0

        if touch_df is None or len(touch_df) == 0:
            return features

        df = touch_df.sort_values(by="time").copy()

        # Handle missing actions by treating rows with actionType == 0 as new stroke start
        # Fill missing pointerIDs with 0
        if "pointerID" not in df.columns:
            df["pointerID"] = 0
        df["pointerID"] = df["pointerID"].fillna(0).astype(int)

        # Create a stroke grouping ID
        # Accumulate actionType == 0 (finger down). If actionType is missing, it will inherit the current stroke.
        is_down = (df["actionType"] == 0).astype(int)
        df["stroke_id"] = is_down.cumsum()

        # Extract features per stroke
        swipes = []
        taps = []

        all_pressures = []
        all_areas = []
        all_orientations = []

        # Group by stroke_id and pointerID (to handle multi-touch correctly)
        for (_, _), group in df.groupby(["stroke_id", "pointerID"]):
            if len(group) < 2:
                # Need at least 2 points to distinguish movement/duration
                continue

            # Pressure, Area, Orientation stats for the stroke
            # Area = pi * touchMajor * touchMinor
            touch_major = group["touchMajor"].fillna(0.0)
            touch_minor = group["touchMinor"].fillna(0.0)
            area = np.pi * touch_major * touch_minor
            
            all_pressures.extend(group["pressure"].dropna().tolist())
            all_areas.extend(area.dropna().tolist())
            all_orientations.extend(group["fingerOrientation"].dropna().tolist())

            # Start and End points
            p_start = group.iloc[0]
            p_end = group.iloc[-1]

            x_s, y_s = p_start["Xvalue"], p_start["Yvalue"]
            x_e, y_e = p_end["Xvalue"], p_end["Yvalue"]
            t_s, t_e = p_start["time"], p_end["time"]

            # Euclidean Distance
            dist = np.sqrt((x_e - x_s)**2 + (y_e - y_s)**2)
            duration = (t_e - t_s).total_seconds()

            if dist > self.swipe_threshold:
                # Swipe
                direction = np.arctan2(y_e - y_s, x_e - x_s) # Swipe angle
                speed = dist / max(duration, 0.001)

                # Instantaneous velocity & acceleration within the swipe
                inst_vels = []
                inst_accs = []
                
                # Sort group by time
                sorted_group = group.sort_values(by="time")
                times = sorted_group["time"].tolist()
                xs = sorted_group["Xvalue"].tolist()
                ys = sorted_group["Yvalue"].tolist()

                for j in range(len(sorted_group) - 1):
                    dt = (times[j+1] - times[j]).total_seconds()
                    if dt > 0:
                        ds = np.sqrt((xs[j+1] - xs[j])**2 + (ys[j+1] - ys[j])**2)
                        inst_vels.append(ds / dt)

                for j in range(len(inst_vels) - 1):
                    dt = (times[j+2] - times[j+1]).total_seconds()
                    if dt > 0:
                        inst_accs.append((inst_vels[j+1] - inst_vels[j]) / dt)

                swipes.append({
                    "distance": dist,
                    "duration": duration,
                    "speed": speed,
                    "direction": direction,
                    "vels": inst_vels,
                    "accs": inst_accs
                })
            else:
                # Tap
                taps.append({
                    "duration": duration
                })

        features["swipe_count"] = float(len(swipes))
        features["tap_count"] = float(len(taps))

        # Helper to compute array stats
        def add_stats(vals, prefix):
            if vals:
                features[f"{prefix}_mean"] = float(np.mean(vals))
                features[f"{prefix}_std"] = float(np.std(vals)) if len(vals) > 1 else 0.0
                features[f"{prefix}_median"] = float(np.median(vals))
                features[f"{prefix}_min"] = float(np.min(vals))
                features[f"{prefix}_max"] = float(np.max(vals))

        # Add Swipe statistics
        if swipes:
            add_stats([s["distance"] for s in swipes], "swipe_dist")
            add_stats([s["duration"] for s in swipes], "swipe_dur")
            add_stats([s["speed"] for s in swipes], "swipe_speed")
            
            # Circular statistics for angles to prevent wrap-around errors
            dirs = [s["direction"] for s in swipes]
            features["swipe_dir_mean"] = float(np.arctan2(np.mean(np.sin(dirs)), np.mean(np.cos(dirs))))
            r = np.sqrt(np.mean(np.sin(dirs))**2 + np.mean(np.cos(dirs))**2)
            # Clip r to prevent log(0)
            r = max(min(r, 1.0), 1e-9)
            features["swipe_dir_std"] = float(np.sqrt(-2.0 * np.log(r)))
            features["swipe_dir_median"] = float(np.median(dirs))
            features["swipe_dir_min"] = float(np.min(dirs))
            features["swipe_dir_max"] = float(np.max(dirs))

            # Flattens instant velocities and accelerations
            flat_vels = [v for s in swipes for v in s["vels"]]
            flat_accs = [a for s in swipes for a in s["accs"]]
            features["swipe_inst_vel_mean"] = float(np.mean(flat_vels)) if flat_vels else np.nan
            features["swipe_inst_vel_std"] = float(np.std(flat_vels)) if len(flat_vels) > 1 else 0.0
            features["swipe_inst_acc_mean"] = float(np.mean(flat_accs)) if flat_accs else np.nan
            features["swipe_inst_acc_std"] = float(np.std(flat_accs)) if len(flat_accs) > 1 else 0.0

        # Add Tap statistics
        if taps:
            add_stats([t["duration"] for t in taps], "tap_dur")

        # Global session pressure, area, orientation statistics
        add_stats(all_pressures, "touch_press")
        add_stats(all_areas, "touch_area")
        add_stats(all_orientations, "touch_orient")

        return features


class MotionFeatureExtractor:
    """
    Extracts statistical features from raw motion sensors (Accelerometer & Gyroscope).
    For each sensor:
    - X, Y, Z, and Mag (Magnitude)
    - Stats: mean, std, min, max, median, skewness, kurtosis.
    """
    def __init__(self, prefix="acc"):
        self.prefix = prefix
        self.columns = ["Xvalue", "Yvalue", "Zvalue", "Mag"]
        self.stats = ["mean", "std", "min", "max", "median", "skew", "kurt"]
        
        self.feature_names = []
        for col in self.columns:
            for stat in self.stats:
                self.feature_names.append(f"{self.prefix}_{col}_{stat}")

    def extract(self, sensor_df):
        """
        Extracts motion features from sensor_df.
        sensor_df columns: ['Xvalue', 'Yvalue', 'Zvalue']
        """
        features = {name: np.nan for name in self.feature_names}
        if sensor_df is None or len(sensor_df) == 0:
            return features

        df = sensor_df.copy()
        
        # Calculate Magnitude Mag = sqrt(X^2 + Y^2 + Z^2)
        df["Mag"] = np.sqrt(df["Xvalue"]**2 + df["Yvalue"]**2 + df["Zvalue"]**2)

        for col in self.columns:
            series = df[col].dropna()
            if len(series) > 0:
                features[f"{self.prefix}_{col}_mean"] = float(np.mean(series))
                features[f"{self.prefix}_{col}_std"] = float(np.std(series)) if len(series) > 1 else 0.0
                features[f"{self.prefix}_{col}_min"] = float(np.min(series))
                features[f"{self.prefix}_{col}_max"] = float(np.max(series))
                features[f"{self.prefix}_{col}_median"] = float(np.median(series))
                # Set bias=False for sample skew/kurtosis, avoid division by zero when standard deviation is zero
                std_val = np.std(series)
                if len(series) > 2 and std_val > 1e-9:
                    features[f"{self.prefix}_{col}_skew"] = float(skew(series, bias=False, nan_policy="omit"))
                else:
                    features[f"{self.prefix}_{col}_skew"] = 0.0
                
                if len(series) > 3 and std_val > 1e-9:
                    features[f"{self.prefix}_{col}_kurt"] = float(kurtosis(series, bias=False, nan_policy="omit"))
                else:
                    features[f"{self.prefix}_{col}_kurt"] = 0.0

        return features


class FeatureSelector:
    """
    Implements modular feature selection pipeline:
    1. Removes low variance features.
    2. Removes highly correlated features.
    3. Selects top K features using SelectKBest with ANOVA F-value.
    Saves and loads feature selection models for inference.
    """
    def __init__(self, variance_threshold=0.01, correlation_threshold=0.95, k_best=50):
        self.variance_threshold = variance_threshold
        self.correlation_threshold = correlation_threshold
        self.k_best = k_best
        
        self.variance_selector = None
        self.kbest_selector = None
        self.selected_features = None  # List of selected feature names
        self.features_to_drop_corr = []  # List of correlated features dropped during training

    def fit(self, X_df, y):
        """
        Fits the selectors on training data.
        X_df: Pandas DataFrame of features
        y: Target label series
        """
        X = X_df.copy()
        original_cols = list(X.columns)

        # 1. Low Variance Filter
        self.variance_selector = VarianceThreshold(threshold=self.variance_threshold)
        self.variance_selector.fit(X)
        var_mask = self.variance_selector.get_support()
        X = X.loc[:, var_mask]
        print(f"Variance Filter: Kept {X.shape[1]} / {len(original_cols)} features.")

        # 2. Correlation Filter (Drop highly correlated features)
        corr_matrix = X.corr().abs()
        upper = corr_matrix.where(np.triu(np.ones(corr_matrix.shape), k=1).astype(bool))
        
        self.features_to_drop_corr = [col for col in upper.columns if any(upper[col] > self.correlation_threshold)]
        X = X.drop(columns=self.features_to_drop_corr)
        print(f"Correlation Filter: Dropped {len(self.features_to_drop_corr)} correlated features. Kept {X.shape[1]}.")

        # 3. SelectKBest Filter
        actual_k = min(self.k_best, X.shape[1])
        self.kbest_selector = SelectKBest(score_func=f_classif, k=actual_k)
        self.kbest_selector.fit(X, y)
        
        kbest_mask = self.kbest_selector.get_support()
        self.selected_features = list(X.columns[kbest_mask])
        print(f"SelectKBest: Selected top {len(self.selected_features)} features.")
        return self

    def transform(self, X_df):
        """
        Applies feature selection on new data.
        X_df: Pandas DataFrame of features
        """
        if self.selected_features is None:
            raise ValueError("FeatureSelector has not been fitted yet.")
        
        # Simply keep the columns that were selected during fit
        # If any selected feature is missing (should not happen on identical schema), fill with 0
        cols_to_keep = [col for col in self.selected_features if col in X_df.columns]
        X_trans = X_df[cols_to_keep].copy()
        
        # Handle cases where some selected features might be missing in test
        missing = set(self.selected_features) - set(X_trans.columns)
        for col in missing:
            X_trans[col] = 0.0
            
        # Ensure column ordering matches selected_features
        X_trans = X_trans[self.selected_features]
        return X_trans

    def save(self, filepath):
        """Saves selector to joblib file."""
        joblib.dump(self, filepath)
        print(f"FeatureSelector saved to {filepath}")

    @staticmethod
    def load(filepath):
        """Loads selector from joblib file."""
        if not os.path.exists(filepath):
            raise FileNotFoundError(f"FeatureSelector file not found at {filepath}")
        return joblib.load(filepath)
